package com.example.payment.integrationtest.paymentgateway;

import static com.github.tomakehurst.wiremock.client.WireMock.aResponse;
import static com.github.tomakehurst.wiremock.client.WireMock.equalToJson;
import static com.github.tomakehurst.wiremock.client.WireMock.postRequestedFor;
import static com.github.tomakehurst.wiremock.client.WireMock.stubFor;
import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static com.github.tomakehurst.wiremock.client.WireMock.verify;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.github.tomakehurst.wiremock.WireMockServer;
import com.github.tomakehurst.wiremock.core.WireMockConfiguration;
import java.math.BigDecimal;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Verifies the contract between {@link HttpPaymentGateway} and the payment provider's REST
 * API: the JSON request we send, and every JSON/status response shape we must read back
 * correctly, including an outright refusal (402) and an unexpected server error.
 */
class HttpPaymentGatewayTest {

    private WireMockServer provider;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() {
        provider = new WireMockServer(WireMockConfiguration.options().dynamicPort());
        provider.start();
        var client = RestClient.builder().baseUrl(provider.baseUrl()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopProvider() {
        provider.stop();
    }

    @Test
    void sends_the_reference_and_amount_as_the_provider_expects_them() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"approved\"}")));

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        verify(postRequestedFor(urlEqualTo("/v1/authorizations"))
                .withRequestBody(equalToJson(
                        "{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", true, false)));
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"approved\"}")));

        var outcome = gateway.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"declined\"}")));

        var outcome = gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_request_outright_with_402_is_treated_as_declined() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(402)));

        var outcome = gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_provider_error_is_surfaced_instead_of_silently_declined() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(500)));

        assertThatThrownBy(() -> gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    @Test
    void an_unrecognized_status_body_is_treated_as_declined() {
        provider.stubFor(
                com.github.tomakehurst.wiremock.client.WireMock.post(urlEqualTo("/v1/authorizations"))
                        .willReturn(aResponse().withStatus(200).withHeader("Content-Type", "application/json")
                                .withBody("{\"status\":\"pending\"}")));

        var outcome = gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "EUR"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }
}

